import React, { useState, useEffect } from "react";

const API = "http://127.0.0.1:8000/api";

function App() {
  const [screen, setScreen] = useState("auth");
  const [user, setUser] = useState({ role: "guest", id: 0, name: "Misafir" });
  const [items, setItems] = useState([]);
  const [categories, setCategories] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [history, setHistory] = useState([]);
  const [allItems, setAllItems] = useState([]);
  const [stats, setStats] = useState({ total_items: 0, pending_approvals: 0 });

  const [search, setSearch] = useState("");
  const [filterType, setFilterType] = useState("");
  const [filterCategory, setFilterCategory] = useState("");

  // İlan Formu State
  const [itemTitle, setItemTitle] = useState("");
  const [itemDesc, setItemDesc] = useState("");
  const [itemCat, setItemCat] = useState("");
  const [itemLoc, setItemLoc] = useState("");
  const [itemType, setItemType] = useState("lost");

  const [regName, setRegName] = useState("");
  const [regEmail, setRegEmail] = useState("");
  const [regPassword, setRegPassword] = useState("");
  const [regRole, setRegRole] = useState("user");

  useEffect(() => {
    loadMeta();
  }, []);

  useEffect(() => {
    if (screen === "home") loadItems();
    if (screen === "security") loadSecurityPanel();
    if (screen === "profile") loadProfileData();
  }, [screen]);

  const loadMeta = async () => {
    try {
      const resCat = await fetch(`${API}/items/meta/categories`);
      const cats = await resCat.json();
      setCategories(cats);
      if (cats.length > 0) setItemCat(cats[0].id);
    } catch (e) {
      console.log(e);
    }
  };

  const loadItems = async () => {
    try {
      const res = await fetch(`${API}/items`);
      if (res.ok) {
        const data = await res.json();
        setItems(data);
      }
    } catch (e) {
      console.log("İlanlar yüklenirken hata oluştu:", e);
    }
  };
  const handleClaimItem = async (itemId) => {
    if (user.id === 0 || user.role === "guest") {
      return alert(
        "Bu işlemi yapabilmek için lütfen önce sisteme giriş yapın!",
      );
    }

    try {
      const res = await fetch(`${API}/items/claim/${itemId}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          claimerId: user.id,
          claimerName: user.name,
          claimerEmail: user.email, // <-- Sisteme giriş yaptığın kurumsal e-postayı karşıya gönderiyoruz!
        }),
      });

      if (res.ok) {
        alert(
          "Bildiriminiz ilan sahibine başarıyla iletildi! E-posta bilgileriniz paylaşıldı.",
        );
      } else {
        alert("Talep iletilirken bir sorun oluştu.");
      }
    } catch (e) {
      console.log("Talep hatası:", e);
    }
  };
  const loadSecurityPanel = async () => {
    const res = await fetch(`${API}/admin/all-items`);
    const data = await res.json();
    setAllItems(data);

    const resStats = await fetch(`${API}/admin/stats`);
    const s = await resStats.json();
    setStats(s);
  };

  const loadProfileData = async () => {
    const resNotif = await fetch(`${API}/notifications/${user.id}`);
    const notifs = await resNotif.json();
    setNotifications(notifs);

    const resHist = await fetch(`${API}/items/history/${user.id}`);
    const hist = await resHist.json();
    setHistory(hist);
  };

  const login = async (email, password) => {
    const res = await fetch(`${API}/auth/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });
    if (!res.ok) return alert("Giriş bilgileri hatalı!");
    const data = await res.json();
    setUser(data);
    setScreen("home");
  };

  const register = async () => {
    const res = await fetch(`${API}/auth/register`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: regName,
        email: regEmail,
        password: regPassword,
        role: regRole,
      }),
    });
    if (res.ok) {
      alert("Kayıt başarılı! Giriş yapabilirsiniz.");
      setScreen("auth");
    } else {
      const err = await res.json();
      alert("Hata: " + err.detail);
    }
  };

  const submitItem = async () => {
    // ⚠️ Küçük Güvenlik Kontrolü: Form alanları boş gitmesin
    if (!itemTitle.trim() || !itemDesc.trim() || !itemLoc.trim()) {
      return alert("Lütfen tüm alanları (Başlık, Açıklama ve Konum) doldurun!");
    }

    const res = await fetch(`${API}/items`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: itemTitle,
        description: itemDesc,
        category_id: parseInt(itemCat) || categories[0]?.id,
        location_text: itemLoc,
        type: itemType,
        user_id: user.id,
      }),
    });
    if (res.ok) {
      alert(
        "İlan başarıyla oluşturuldu! Güvenlik onayından sonra listelenecektir.",
      );
      setItemTitle("");
      setItemDesc("");
      setItemLoc("");
      setScreen("home");
    } else {
      alert("İlan gönderilirken sunucu hatası oluştu.");
    }
  };

  const approveItem = async (id) => {
    const res = await fetch(
      `${API}/admin/items/${id}/approve?admin_id=${user.id}`,
      { method: "PUT" },
    );
    if (res.ok) {
      alert("İlan onaylandı ve canlıya alındı!");
      setScreen("home");
    }
  };

  return (
    <div>
      <nav className="navbar navbar-expand-lg navbar-dark bg-dark">
        <div className="container">
          <span
            className="navbar-brand pointer"
            onClick={() => setScreen("home")}
          >
            🎓 Kampüs Eşya Portal
          </span>
          {screen !== "auth" && screen !== "register" && (
            <div className="navbar-nav ms-auto">
              <div className="d-flex align-items-center">
                <span
                  className="nav-link pointer me-3"
                  onClick={() => setScreen("home")}
                >
                  Ana Sayfa
                </span>
                {user.role !== "guest" && (
                  <span
                    className="nav-link pointer me-3"
                    onClick={() => setScreen("createItem")}
                  >
                    İlan Oluştur
                  </span>
                )}
                {user.role !== "guest" && (
                  <span
                    className="nav-link pointer me-3"
                    onClick={() => setScreen("profile")}
                  >
                    Profilim ({notifications.length})
                  </span>
                )}
                {["admin", "security"].includes(user.role) && (
                  <span
                    className="nav-link pointer me-3 text-warning"
                    onClick={() => setScreen("security")}
                  >
                    👮 Yetkili Paneli
                  </span>
                )}
                <button
                  className="btn btn-sm btn-danger ms-2"
                  onClick={() => window.location.reload()}
                >
                  Çıkış
                </button>
              </div>
            </div>
          )}
        </div>
      </nav>

      <div className="hero">
        <h2>
          {screen === "auth" || screen === "register"
            ? "Kampüs Kayıp & Bulunan Eşya Portalı"
            : `Hoş Geldiniz, ${user.name}`}
        </h2>
        <p>
          {screen === "auth" || screen === "register"
            ? "Güvenli ve Hızlı Kampüs Dayanışma Sistemi"
            : `Sistem Rol Yetkiniz: [${user.role.toUpperCase()}]`}
        </p>
      </div>

      <div className="container">
        {screen === "auth" && (
          <div className="row justify-content-center">
            <div className="col-md-4 card p-4 shadow-sm text-center">
              <h4>Sisteme Giriş</h4>
              <input
                type="email"
                id="emailInput"
                className="form-control mb-2"
                placeholder="E-posta"
                defaultValue="ahmet@ogrenci.edu.tr"
              />
              <input
                type="password"
                id="passInput"
                className="form-control mb-3"
                placeholder="Şifre"
                defaultValue="123"
              />
              <button
                className="btn btn-primary w-100 mb-2"
                onClick={() =>
                  login(
                    document.getElementById("emailInput").value,
                    document.getElementById("passInput").value,
                  )
                }
              >
                Giriş Yap
              </button>
              <button
                className="btn btn-outline-secondary w-100 mb-3"
                onClick={() => {
                  setUser({ role: "guest", id: 0, name: "Misafir" });
                  setScreen("home");
                }}
              >
                🏃 Misafir Devam Et
              </button>
              <span
                className="text-muted small pointer text-primary"
                onClick={() => setScreen("register")}
              >
                Hesabınız yok mu? Kayıt Ol
              </span>
            </div>
          </div>
        )}

        {screen === "register" && (
          <div className="row justify-content-center">
            <div className="col-md-4 card p-4 shadow-sm">
              <h4 className="text-center mb-3">Yeni Hesap Oluştur</h4>
              <input
                type="text"
                className="form-control mb-2"
                placeholder="Ad Soyad"
                onChange={(e) => setRegName(e.target.value)}
              />
              <input
                type="email"
                className="form-control mb-2"
                placeholder="E-posta Adresi"
                onChange={(e) => setRegEmail(e.target.value)}
              />
              <input
                type="password"
                className="form-control mb-2"
                placeholder="Şifre"
                onChange={(e) => setRegPassword(e.target.value)}
              />
              <select
                className="form-select mb-3"
                onChange={(e) => setRegRole(e.target.value)}
              >
                <option value="user">Öğrenci / Personel</option>
                <option value="security">Kampüs Güvenliği</option>
                <option value="admin">Kampüs Yönetimi / Admin</option>
              </select>
              <button className="btn btn-success w-100 mb-2" onClick={register}>
                Kayıt Ol
              </button>
              <center>
                <span
                  className="text-primary pointer small"
                  onClick={() => setScreen("auth")}
                >
                  Giriş Yapın
                </span>
              </center>
            </div>
          </div>
        )}

        {screen === "home" && (
          <div className="row">
            <div className="col-md-3 bg-white p-3 rounded shadow-sm mb-3">
              <h5> Filtreleme</h5>
              <div className="input-group mb-2">
                <input
                  type="text"
                  className="form-control"
                  placeholder="Kelime ile ara..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
                <button className="btn btn-primary" onClick={loadItems}>
                  Ara
                </button>
              </div>
              <select
                className="form-select mb-2"
                onChange={(e) => setFilterType(e.target.value)}
              >
                <option value="">Tüm Türler</option>
                <option value="lost">Kayıp Eşyalar</option>
                <option value="found">Bulunan Eşyalar</option>
              </select>
              <select
                className="form-select"
                onChange={(e) => setFilterCategory(e.target.value)}
              >
                <option value="">Tüm Kategoriler</option>
                {categories.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-md-9">
              <h4 className="mb-3">📢 Aktif Kampüs İlanları</h4>
              <div className="row">
                {items.length === 0 ? (
                  <p className="text-muted text-center mt-4">
                    Aktif ilan bulunmuyor.
                  </p>
                ) : (
                  items.map((i) => (
                    <div className="col-md-6 mb-3" key={i.id}>
                      <div
                        className={`card p-3 border-start border-4 ${i.type === "lost" ? "border-danger" : "border-success"}`}
                      >
                        <h5>
                          {i.title}{" "}
                          <span
                            className={`badge ${i.type === "lost" ? "bg-danger" : "bg-success"}`}
                          >
                            {i.type === "lost" ? "KAYIP" : "BULUNDU"}
                          </span>
                        </h5>
                        <p className="small text-secondary mb-1">
                          {i.description}
                        </p>
                        <p className="text-muted small mb-0">
                          📍 Konum: {i.image_url || "Belirtilmedi"}
                        </p>

                        {user.id !== i.user_id && (
                          <button
                            className={`btn btn-sm w-100 mt-2 ${i.type === "lost" ? "btn-outline-danger" : "btn-outline-success"}`}
                            onClick={() => handleClaimItem(i.id)}
                          >
                            {i.type === "lost"
                              ? "🔍 Bu Eşyayı Ben Buldum!"
                              : "🙋 Bu Eşya Benim!"}
                          </button>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        )}

        {screen === "createItem" && (
          <div className="row justify-content-center">
            <div className="col-md-6 card p-4 shadow-sm">
              <h4>🆕 Yeni İlan Bildir</h4>
              <input
                type="text"
                className="form-control mb-2"
                placeholder="Eşya Başlığı"
                value={itemTitle}
                onChange={(e) => setItemTitle(e.target.value)}
              />
              <textarea
                className="form-control mb-2"
                placeholder="Açıklama..."
                value={itemDesc}
                onChange={(e) => setItemDesc(e.target.value)}
              ></textarea>

              <label className="small text-muted">Kategori</label>
              <select
                className="form-select mb-2"
                value={itemCat}
                onChange={(e) => setItemCat(e.target.value)}
              >
                {categories.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>

              <label className="small text-muted">
                Eşyanın Bulunduğu / Kaybolduğu Yer (Serbest Metin)
              </label>
              <input
                type="text"
                className="form-control mb-2"
                placeholder="Örn: Yemekhane arkasındaki çimler"
                value={itemLoc}
                onChange={(e) => setItemLoc(e.target.value)}
              />

              <label className="small text-muted">İlan Amacı</label>
              <select
                className="form-select mb-3"
                onChange={(e) => setItemType(e.target.value)}
              >
                <option value="lost">Eşyamı Kaybettim</option>
                <option value="found">Eşya Buldum</option>
              </select>
              <button className="btn btn-success w-100" onClick={submitItem}>
                İlanı Gönder
              </button>
            </div>
          </div>
        )}

        {screen === "profile" && (
          <div className="row">
            <div className="col-md-6 mb-3">
              <div className="card p-3 shadow-sm bg-warning bg-opacity-10">
                <h5>🔔 Akıllı Eşleşme Bildirimleri</h5>
                {notifications.map((n) => {
                  const parts = n.message.split("||");
                  const mainMessage = parts[0];
                  const emailAddress = parts[1];

                  if (emailAddress) {
                    return (
                      <div className="mb-2" key={n.id}>
                        <div className="list-group-item text-dark small p-3 bg-white rounded border-start border-primary border-4 shadow-sm">
                          <div className="fw-semibold text-danger mb-2">
                            {mainMessage}
                          </div>
                          <div className="d-flex gap-2 mt-2">
                            {/* Gerçek Saf Mail Linki */}
                            <a
                              href={`mailto:${emailAddress}?subject=Kampus%20Esya%20Portali`}
                              className="btn btn-primary btn-sm flex-grow-1 text-white fw-bold text-decoration-none text-center"
                              style={{ padding: "6px" }}
                            >
                              ✉️ Mail At
                            </a>
                            {/* Tek Tıkla Kopyalama Butonu (about:blank hatasına karşı panzehir) */}
                            <button
                              onClick={() => {
                                navigator.clipboard.writeText(emailAddress);
                                alert(
                                  "E-posta adresi panoya kopyalandı! Direkt Gmail'e yapıştırabilirsiniz: " +
                                    emailAddress,
                                );
                              }}
                              className="btn btn-outline-secondary btn-sm fw-bold"
                            >
                              📋 Kopyala
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  } else {
                    return (
                      <div
                        className="list-group-item text-secondary small mb-1 p-2 bg-white rounded border-start border-warning border-3"
                        key={n.id}
                      >
                        ⚠️ {n.message}
                      </div>
                    );
                  }
                })}
              </div>
            </div>
          </div>
        )}

        {screen === "security" && (
          <div className="row">
            <div className="col-md-6 mb-3">
              <div className="card p-3 bg-primary text-white text-center">
                <h6>Toplam İlan</h6>
                <h2>{stats.total_items}</h2>
              </div>
            </div>
            <div className="col-md-6 mb-3">
              <div className="card p-3 bg-danger text-white text-center">
                <h6>Onay Bekleyenler</h6>
                <h2>{stats.pending_approvals}</h2>
              </div>
            </div>
            <div className="col-12 card p-4 mt-2">
              <h4>👮 Güvenlik Onay Yönetimi</h4>
              <table className="table table-bordered table-striped mt-2">
                <thead>
                  <tr>
                    <th>No</th>
                    <th>Eşya Adı</th>
                    <th>Açıklama</th>
                    <th>İşlem</th>
                  </tr>
                </thead>
                <tbody>
                  {allItems
                    .filter((i) => i.status === "pending")
                    .map((i) => (
                      <tr key={i.id}>
                        <td>{i.id}</td>
                        <td>{i.title}</td>
                        <td>{i.description}</td>
                        <td>
                          <button
                            className="btn btn-sm btn-success"
                            onClick={() => approveItem(i.id)}
                          >
                            Onayla ve Yayınla
                          </button>
                        </td>
                      </tr>
                    ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;
